import type { AppState, DailyLog } from '../types';
import { calculateDateForDayNumber } from './storage';
import { metricStatus } from './entered';
import { planDailyWrites } from './cloudMerge';

/**
 * NON-DESTRUCTIVE legacy-state repair helpers.
 *
 * Background: states generated by older builds can carry (a) day dates that do not
 * match settings.startDate (overlaps/duplicates) and (b) pre-filled sleepHours on
 * untouched template days with no entered flags. Together these make planDailyWrites
 * plan every template day and trip the collision guard, so the first cloud save can
 * never succeed on such a device.
 *
 * Rules (owner-approved constraints):
 *  - NOTHING here mutates input state. Every function is pure; repairs return copies.
 *  - Ambiguous values (e.g. sleep 7.5 with no entered flag) are NEVER discarded by
 *    value alone: they are surfaced in a preview and only changed by an explicit,
 *    per-item user-confirmed repair call.
 *  - Repairs record provenance (old date / old sleep) on the repaired log itself so
 *    the change is reversible and reviewable, and it syncs to the cloud with the log.
 *  - The collision guard in planDailyWrites is untouched and remains the backstop.
 */

export interface DateMismatch {
  day: number;
  currentDate: string | undefined;
  derivedDate: string;
}

export interface AmbiguousSleep {
  day: number;
  sleepHours: number;
}

export interface LegacyRepairPreview {
  /** Days whose stored date differs from the date derived from settings.startDate. */
  dateMismatches: DateMismatch[];
  /** Days with a stored sleep value that was never confirmed by the user (metricStatus 'unconfirmed'). */
  ambiguousSleep: AmbiguousSleep[];
  /** Collision messages the save planner would produce against the current (empty) cloud right now. */
  plannedCollisions: string[];
  /** True when nothing needs review: save may proceed without any repair. */
  isClean: boolean;
}

/** Days with an unconfirmed (never-entered) stored sleep value. Pure. */
export function detectAmbiguousSleep(logs: { [day: string]: DailyLog } | undefined): AmbiguousSleep[] {
  const out: AmbiguousSleep[] = [];
  for (const [k, log] of Object.entries(logs || {})) {
    const day = Number(k);
    if (!log || !Number.isFinite(day)) continue;
    if (metricStatus(log, 'sleep') === 'unconfirmed') {
      out.push({ day, sleepHours: log.sleepHours as number });
    }
  }
  return out.sort((a, b) => a.day - b.day);
}

/** Days whose stored date disagrees with settings.startDate. Pure. */
export function detectDateMismatches(state: AppState): DateMismatch[] {
  const start = state?.settings?.startDate;
  if (!start) return [];
  const out: DateMismatch[] = [];
  for (const [k, log] of Object.entries(state.dailyLogs || {})) {
    const day = Number(k);
    if (!log || !Number.isFinite(day)) continue;
    const derived = calculateDateForDayNumber(start, day);
    if (derived && log.date !== derived) {
      out.push({ day, currentDate: log.date, derivedDate: derived });
    }
  }
  return out.sort((a, b) => a.day - b.day);
}

/**
 * Builds the full pre-save review. Pure: the input state is not modified.
 * `plannedCollisions` plans against an EMPTY cloud, which reproduces the first-link
 * failure a legacy device hits on its very first save.
 */
export function buildRepairPreview(state: AppState, nowIso: string = new Date().toISOString()): LegacyRepairPreview {
  const dateMismatches = detectDateMismatches(state);
  const ambiguousSleep = detectAmbiguousSleep(state.dailyLogs as any);
  let plannedCollisions: string[] = [];
  try {
    plannedCollisions = planDailyWrites((state.dailyLogs || {}) as any, [], {}, nowIso).collisions;
  } catch {
    plannedCollisions = ['<planner failed on this state>'];
  }
  return {
    dateMismatches,
    ambiguousSleep,
    plannedCollisions,
    isClean: dateMismatches.length === 0 && ambiguousSleep.length === 0 && plannedCollisions.length === 0,
  };
}

/**
 * Pre-save gate. Returns null when the save may proceed untouched; otherwise the
 * preview the UI must show ("Review older records") BEFORE any save is attempted.
 * Never repairs by itself.
 */
export function preflightSaveReview(state: AppState, nowIso?: string): LegacyRepairPreview | null {
  const preview = buildRepairPreview(state, nowIso);
  return preview.isClean ? null : preview;
}

/**
 * CONSENTED repair: re-derive every mismatched log date from settings.startDate.
 * Returns a NEW state; the input is not modified. Each repaired log keeps ALL user
 * data and gains `legacyDate` (its previous date) as provenance. Logs whose date was
 * already correct are returned as-is (same object reference).
 */
export function applyDateRepair(state: AppState): AppState {
  const start = state?.settings?.startDate;
  if (!start) return state;
  const logs = state.dailyLogs || {};
  const nextLogs: typeof logs = { ...logs };
  for (const { day, currentDate, derivedDate } of detectDateMismatches(state)) {
    const log = logs[day] ?? (logs as any)[String(day)];
    if (!log) continue;
    nextLogs[day as any] = {
      ...log,
      date: derivedDate,
      // provenance: keep the first-known legacy date; do not overwrite an existing one
      legacyDate: (log as any).legacyDate ?? currentDate,
    } as DailyLog;
  }
  return { ...state, dailyLogs: nextLogs };
}

/**
 * CONSENTED repair: clear the stored sleep value ONLY on the explicitly listed days
 * (the ones the user confirmed were pre-filled placeholders). Returns a NEW state.
 * Each repaired log gains `legacySleepHours` with the removed value as provenance.
 * Days not in the list are never touched, so an ambiguous-but-real value survives
 * unless the owner explicitly clears it.
 */
export function applySleepRepair(state: AppState, days: number[]): AppState {
  const wanted = new Set(days);
  const logs = state.dailyLogs || {};
  const nextLogs: typeof logs = { ...logs };
  for (const [k, log] of Object.entries(logs)) {
    const day = Number(k);
    if (!wanted.has(day) || !log) continue;
    if (metricStatus(log, 'sleep') !== 'unconfirmed') continue; // never touch entered/missing values
    const copy: any = { ...log };
    copy.legacySleepHours = (log as any).legacySleepHours ?? log.sleepHours;
    delete copy.sleepHours;
    nextLogs[day as any] = copy;
  }
  return { ...state, dailyLogs: nextLogs };
}/**
 * REVERT for applyDateRepair: puts each recorded legacyDate back, ONLY when the log
 * still holds the repaired (derived) date - never clobbers a date the user changed
 * after the repair. Clears the provenance field on reverted logs. Returns a NEW state.
 */
export function revertDateRepair(state: AppState): AppState {
  const start = state?.settings?.startDate;
  if (!start) return state;
  const logs = state.dailyLogs || {};
  const nextLogs: typeof logs = { ...logs };
  for (const [k, log] of Object.entries(logs)) {
    const day = Number(k);
    if (!log || !Number.isFinite(day)) continue;
    const legacyDate = (log as any).legacyDate as string | undefined;
    if (!legacyDate) continue;
    const derived = calculateDateForDayNumber(start, day);
    if (log.date !== derived) continue; // edited since repair: leave alone
    const copy: any = { ...log, date: legacyDate };
    delete copy.legacyDate;
    nextLogs[day as any] = copy;
  }
  return { ...state, dailyLogs: nextLogs };
}

/**
 * REVERT for applySleepRepair: restores legacySleepHours on the listed days (or all
 * recorded ones when omitted), ONLY when no sleep value was entered since the repair.
 * Clears the provenance field on reverted logs. Returns a NEW state.
 */
export function revertSleepRepair(state: AppState, days?: number[]): AppState {
  const wanted = days ? new Set(days) : null;
  const logs = state.dailyLogs || {};
  const nextLogs: typeof logs = { ...logs };
  for (const [k, log] of Object.entries(logs)) {
    const day = Number(k);
    if (!log || !Number.isFinite(day)) continue;
    if (wanted && !wanted.has(day)) continue;
    const legacySleep = (log as any).legacySleepHours as number | undefined;
    if (legacySleep === undefined) continue;
    if (log.sleepHours !== undefined) continue; // user entered a value since: leave alone
    const copy: any = { ...log, sleepHours: legacySleep };
    delete copy.legacySleepHours;
    nextLogs[day as any] = copy;
  }
  return { ...state, dailyLogs: nextLogs };
}

/**
 * CONSENTED confirmation for ambiguous sleep values the owner reviewed and chose to
 * KEEP AS THEIR REAL ENTRIES ("keep as logged"). Sets entered.sleep = true - the app's
 * native "user confirmed this entry" semantics, the same flag the sleep modal sets when
 * the person taps "That's right". The stored value itself is NEVER changed.
 *
 * Each confirmed day gains provenance `legacySleepConfirmedByReview: true` so the
 * confirmation can be undone (see undoSleepConfirmation) and stays distinguishable from
 * values the user typed directly. Only days currently 'unconfirmed' with a stored value
 * are touched. Returns a NEW state.
 */
export function confirmSleepEntries(state: AppState, days: number[]): AppState {
  const wanted = new Set(days);
  const logs = state.dailyLogs || {};
  const nextLogs: typeof logs = { ...logs };
  for (const [k, log] of Object.entries(logs)) {
    const day = Number(k);
    if (!wanted.has(day) || !log) continue;
    if (metricStatus(log, 'sleep') !== 'unconfirmed' || log.sleepHours === undefined) continue;
    nextLogs[day as any] = {
      ...log,
      entered: { ...(log.entered || {}), sleep: true },
      legacySleepConfirmedByReview: true,
    } as DailyLog;
  }
  return { ...state, dailyLogs: nextLogs };
}

/**
 * UNDO for confirmSleepEntries: removes the review-added confirmation flag and its
 * provenance, returning the day to 'unconfirmed' (the pre-save gate will ask again).
 * Never touches confirmations the flow did not add (no provenance marker = no undo).
 * The stored sleep value is never changed. Returns a NEW state.
 */
export function undoSleepConfirmation(state: AppState, days?: number[]): AppState {
  const wanted = days ? new Set(days) : null;
  const logs = state.dailyLogs || {};
  const nextLogs: typeof logs = { ...logs };
  for (const [k, log] of Object.entries(logs)) {
    const day = Number(k);
    if (!log || !Number.isFinite(day)) continue;
    if (wanted && !wanted.has(day)) continue;
    if ((log as any).legacySleepConfirmedByReview !== true) continue;
    const copy: any = { ...log, entered: { ...(log.entered || {}) } };
    if (copy.entered.sleep === true) {
      delete copy.entered.sleep;
      if (Object.keys(copy.entered).length === 0) delete copy.entered;
    }
    delete copy.legacySleepConfirmedByReview;
    nextLogs[day as any] = copy;
  }
  return { ...state, dailyLogs: nextLogs };
}
